-- TASK-0065 Open Hand teaching items: ap-statistics (2 items). Generated by
-- scripts/content-seed/task0065_load/build_load_sql.py. Idempotent: re-running
-- skips content_keys already present in the target pack.
do $oht0065$
declare
  v_subject text := 'ap-statistics';
  v_tsv uuid := 'dae3c72e-82ca-4960-9552-1b034bd347e5';
  v_owner uuid := (select p.user_id from app.profiles p where p.user_id = 'f5a26c6b-3566-4d58-9e97-979fbb947564');
  v_items jsonb := $oht0065json$[{"content_key":"APSTATS-OHT-1.10-r2","topic_code":"1.10","title":"The Investigative Question Revisited and Data Collection","stem":"Researchers want to investigate whether adults who regularly walk to work have different sleep durations from adults who do not. They enroll adults today and record their usual commuting habits. For the next six months, researchers measure each adult’s sleep duration weekly and compare the two groups. Researchers do not assign commuting methods or ask anyone to change their habits. Which classification and explanation best describe this study?","choices":[{"choice_key":"A","choice_text":"A prospective observational study, because researchers impose no treatment and collect sleep data going forward from enrollment.","is_correct":true,"rationale":"Researchers record commuting habits without assigning or changing them, so the study is observational. The sleep measurements are collected over the next six months, making it prospective."},{"choice_key":"B","choice_text":"A retrospective observational study, because the adults’ commuting habits existed before enrollment.","is_correct":false,"rationale":"The trap is using the age of a habit to determine the study’s time direction. Existing commuting habits do not make this retrospective; researchers collect sleep data going forward rather than looking back through past records. Fix: Locate when the study’s data are collected, not when the subjects’ habits began."},{"choice_key":"C","choice_text":"An experiment, because researchers repeatedly measure the adults’ sleep over six months.","is_correct":false,"rationale":"The trap is treating repeated measurement as an imposed treatment. Tracking sleep over time records an outcome but does not assign or change the adults’ commuting habits. Fix: Ask what treatment researchers imposed before classifying repeated tracking as an experiment."},{"choice_key":"D","choice_text":"An experiment, because researchers compare adults who walk to work with adults who do not.","is_correct":false,"rationale":"The trap is assuming that comparing groups makes a study experimental. These groups arise from existing habits, not treatments imposed by the researchers; observational studies can also compare groups. Fix: Check whether researchers created the groups by imposing treatments or simply recorded existing differences."}]},{"content_key":"APSTATS-OHT-2.12-r2","topic_code":"2.12","title":"Sampling Distributions and the Central Limit Theorem","stem":"Delivery times in a large database have a right-skewed population distribution. For a fixed sample size n, consider all possible random samples of n delivery times drawn with replacement from this database. A dotplot places one dot at the mean of each possible sample. The process is then considered for larger sample sizes. Which statement correctly identifies the dotplot’s distribution and describes what the Central Limit Theorem implies as n grows?","choices":[{"choice_key":"A","choice_text":"The dotplot shows the population distribution of delivery times; the Central Limit Theorem makes that population approximately normal as n grows.","is_correct":false,"rationale":"Population-normality trap: the dots are sample means, not individual population values. Increasing sample size changes the sampling distribution, not the delivery times already in the database. Fix: Identify what one dot represents before deciding which distribution the Central Limit Theorem describes."},{"choice_key":"B","choice_text":"The dotplot shows the sampling distribution of the sample mean; its normal approximation improves as n grows, while the population remains right-skewed.","is_correct":true,"rationale":"Each dot summarizes an entire sample rather than representing one delivery. The Central Limit Theorem applies to the distribution of these sample means: its normal approximation improves with increasing sample size without changing the population’s shape."},{"choice_key":"C","choice_text":"The dotplot shows the distribution of individual delivery times in one sample; the Central Limit Theorem makes those observations approximately normal as n grows.","is_correct":false,"rationale":"Single-sample confusion: this plot combines means from all possible samples, not observations from one sample. The Central Limit Theorem does not promise that individual observations in a large sample will be normally distributed. Fix: Check whether the plotted values are individual measurements or summaries calculated from separate whole samples."},{"choice_key":"D","choice_text":"The dotplot shows the sampling distribution of the sample mean; it must remain strongly right-skewed as n grows because the population is right-skewed.","is_correct":false,"rationale":"Shape-inheritance trap: a sampling distribution need not have the population’s shape. Even with a right-skewed population, the Central Limit Theorem gives an improving normal approximation for the distribution of sample means as sample size grows. Fix: Name the plotted statistic, then apply the Central Limit Theorem to its distribution rather than copying the population’s shape."}]}]$oht0065json$::jsonb;
  v_pv uuid; v_npv int;
  r jsonb; c jsonb;
  v_ci uuid; v_civ uuid; v_key text; v_correct text;
  v_loaded int := 0; v_skipped int := 0; v_released int := 0;
begin
  select count(*) into v_npv
  from app.exam_pack_versions epv join app.exam_packs ep on ep.id = epv.exam_pack_id
  join app.subjects s on s.id = ep.subject_id
  where s.subject_key = v_subject and epv.status = 'published' and epv.retired_at is null;
  if v_npv = 0 then
    raise exception 'task0065: no published, non-retired exam pack version for %', v_subject;
  end if;
  -- Prefer the published pack that already holds teaching items (two exist for
  -- Statistics in Development); otherwise require exactly one.
  select epv.id into v_pv
  from app.exam_pack_versions epv join app.exam_packs ep on ep.id = epv.exam_pack_id
  join app.subjects s on s.id = ep.subject_id
  where s.subject_key = v_subject and epv.status = 'published' and epv.retired_at is null
    and (v_npv = 1 or exists (select 1 from app.open_hand_teaching_items t
                              join app.content_items ci on ci.id = t.content_item_id
                              where ci.exam_pack_version_id = epv.id))
  order by (select count(*) from app.open_hand_teaching_items t join app.content_items ci on ci.id = t.content_item_id
            where ci.exam_pack_version_id = epv.id) desc, epv.id
  limit 1;
  if v_pv is null then
    raise exception 'task0065: % has % published packs and none holds teaching items; pick one explicitly', v_subject, v_npv;
  end if;

  for r in select * from jsonb_array_elements(v_items) loop
    v_key := r->>'content_key';
    if exists (select 1 from app.content_items where exam_pack_version_id = v_pv and content_key = v_key) then
      v_skipped := v_skipped + 1;
      continue;
    end if;
    if jsonb_array_length(r->'choices') <> 4
       or (select count(*) from jsonb_array_elements(r->'choices') x where (x->>'is_correct')::boolean) <> 1 then
      raise exception 'task0065: % must have 4 choices with exactly one correct', v_key;
    end if;
    if not exists (select 1 from app.taxonomy_topics tt where tt.taxonomy_source_version = v_tsv
                   and tt.topic_code = r->>'topic_code') then
      raise exception 'task0065: topic % not in taxonomy %', r->>'topic_code', v_tsv;
    end if;
    select x->>'choice_key' into v_correct from jsonb_array_elements(r->'choices') x
    where (x->>'is_correct')::boolean;

    insert into app.content_items (exam_pack_version_id, content_key, item_type, title, status)
    values (v_pv, v_key, 'mcq', r->>'title', 'draft')
    returning id into v_ci;

    insert into app.content_item_versions (content_item_id, version_num, stem, content_hash, status,
      review_status, rubric_type, evaluator_strategy, canonical_answer_1)
    values (v_ci, 1, r->>'stem', md5(v_key), 'draft', 'tutor_review_pending', 'mcq', 'rule_based_mcq', v_correct)
    returning id into v_civ;

    for c in select * from jsonb_array_elements(r->'choices') loop
      insert into app.mcq_choices (content_item_version_id, choice_key, choice_text, is_correct, rationale)
      values (v_civ, c->>'choice_key', c->>'choice_text', (c->>'is_correct')::boolean, c->>'rationale');
    end loop;

    insert into app.content_item_cells (content_item_version_id, content_item_id, taxonomy_source_version,
      topic_code, skill_code, is_primary, assignment_status, source, model_run_id)
    values (v_civ, v_ci, v_tsv, r->>'topic_code', null, true, 'authored', 'task0065_oht_replacement_2026_10_07',
      'TASK-0065 replacement 2026-10-07, APPROVAL-0129: generate-and-select pipeline (4 non-author checkers + veto) and held-out judges; see task0065-live-replacements-2026-10-07');

    -- Publish gates: enforce_publish_gate (approved review_status),
    -- tg_content_pipeline_guard_publish (published only from reviewed_approved),
    -- enforce_mcq_stem_choice_sync (runs on publish; choices exist by now).
    update app.content_item_versions set status = 'reviewed_approved', review_status = 'question_review_approved',
      approved_by = v_owner, approved_at = now() where id = v_civ;
    update app.content_item_versions set status = 'published', published_at = now() where id = v_civ;
    update app.content_items set status = 'reviewed_approved' where id = v_ci;
    update app.content_items set status = 'published' where id = v_ci;

    insert into app.open_hand_teaching_items (content_item_id, topic_code, source, note)
    values (v_ci, r->>'topic_code', 'generated', 'TASK-0065 replacement 2026-10-07 (APPROVAL-0129)')
    on conflict (content_item_id) do nothing;
    v_loaded := v_loaded + 1;
  end loop;

  -- Return superseded spares (same subject + topic) to scoring.
  with rel as (
    update app.open_hand_teaching_items t set released_at = now()
    from app.content_items ci, app.exam_pack_versions epv, app.exam_packs ep, app.subjects s
    where ci.id = t.content_item_id and epv.id = ci.exam_pack_version_id and ep.id = epv.exam_pack_id
      and s.id = ep.subject_id and s.subject_key = v_subject
      and t.source = 'spare' and t.released_at is null
      and exists (select 1 from app.open_hand_teaching_items g
                  join app.content_items gci on gci.id = g.content_item_id
                  where g.source = 'generated' and g.released_at is null and g.note = 'TASK-0065 replacement 2026-10-07 (APPROVAL-0129)'
                    and g.topic_code = t.topic_code and gci.exam_pack_version_id = v_pv
                    and gci.status = 'published')
    returning t.content_item_id)
  select count(*) into v_released from rel;


  -- Replace: release the old generated row for each replaced topic and retire its item.
  declare
    t text; v_old uuid; v_new int;
  begin
    foreach t in array array['1.10','2.12']::text[] loop
      select tt.content_item_id into v_old from app.open_hand_teaching_items tt
        join app.content_items ci on ci.id = tt.content_item_id
      where ci.exam_pack_version_id = v_pv and tt.topic_code = t and tt.source = 'generated'
        and tt.released_at is null and tt.note = 'TASK-0065 batch 2026-10-06';
      if v_old is null then raise exception 'replace: no active old item for % %', v_subject, t; end if;
      update app.open_hand_teaching_items set released_at = now(), note = note || ' | replaced 2026-10-07 (APPROVAL-0129)' where content_item_id = v_old;
      update app.content_item_versions set status = 'retired', updated_at = now() where content_item_id = v_old and status = 'published';
      update app.content_items set status = 'retired' where id = v_old;
      select count(*) into v_new from app.open_hand_teaching_items tt join app.content_items ci on ci.id = tt.content_item_id
      where ci.exam_pack_version_id = v_pv and tt.topic_code = t and tt.source = 'generated' and tt.released_at is null
        and tt.note = 'TASK-0065 replacement 2026-10-07 (APPROVAL-0129)' and ci.status = 'published';
      if v_new <> 1 then raise exception 'replace: % % has % active new items, expected 1', v_subject, t, v_new; end if;
      if (select count(*) from app.open_hand_teaching_items tt join app.content_items ci on ci.id = tt.content_item_id
          where ci.exam_pack_version_id = v_pv and tt.topic_code = t and tt.released_at is null) <> 1 then
        raise exception 'replace: % % does not have exactly one active teaching row', v_subject, t; end if;
    end loop;
  end;
  raise exception 'REHEARSAL OK %: pack %, loaded %, skipped %', v_subject, v_pv, v_loaded, v_skipped;
  raise notice 'task0065 %: pack %, loaded %, skipped %, spares released %', v_subject, v_pv, v_loaded, v_skipped, v_released;
end
$oht0065$;
